import numpy as np

def normalize_image(image: np.ndarray, mean, std) -> np.ndarray:
    if image.ndim != 3:
        raise ValueError("image must be HxWxC")
    c = image.shape[2]
    mean = np.asarray(mean, dtype=np.float32)
    std = np.asarray(std, dtype=np.float32)
    if mean.shape != (c,) or std.shape != (c,):
        raise ValueError("mean and std must have length C")
    if np.any(std <= 0):
        raise ValueError("std must be positive")
    x = image.astype(np.float32) / 255.0
    return (x - mean.reshape(1, 1, c)) / std.reshape(1, 1, c)

import numpy as np

def binary_segmentation_metrics(pred, target, ignore_index=255) -> dict:
    pred = np.asarray(pred)
    target = np.asarray(target)
    if pred.shape != target.shape:
        raise ValueError("pred and target must have identical shapes")
    valid = target != ignore_index
    p = pred[valid] == 1
    t = target[valid] == 1
    tp = int(np.sum(p & t))
    fp = int(np.sum(p & ~t))
    fn = int(np.sum(~p & t))

    def safe(num, den):
        return 1.0 if den == 0 else float(num / den)

    precision = safe(tp, tp + fp)
    recall = safe(tp, tp + fn)
    dice = safe(2 * tp, 2 * tp + fp + fn)
    iou = safe(tp, tp + fp + fn)
    return {
        "tp": tp, "fp": fp, "fn": fn,
        "precision": precision, "recall": recall,
        "dice": dice, "iou": iou
    }

