import numpy as np

def clean_mask(mask: np.ndarray, kernel_size=3) -> np.ndarray:
    if kernel_size <= 0 or kernel_size % 2 == 0:
        raise ValueError("kernel_size must be a positive odd integer")
    binary = (np.asarray(mask) != 0).astype(np.uint8)
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (kernel_size, kernel_size))
    opened = cv2.morphologyEx(binary, cv2.MORPH_OPEN, kernel, iterations=1)
    closed = cv2.morphologyEx(opened, cv2.MORPH_CLOSE, kernel, iterations=1)
    return (closed != 0).astype(np.uint8)

import numpy as np

def backproject_depth(depth, fx, fy, cx, cy, depth_scale=1000.0, mask=None) -> np.ndarray:
    depth = np.asarray(depth, dtype=np.float64)
    if depth.ndim != 2 or fx <= 0 or fy <= 0 or depth_scale <= 0:
        raise ValueError("invalid inputs")
    valid = np.isfinite(depth) & (depth > 0)
    if mask is not None:
        m = np.asarray(mask, dtype=bool)
        if m.shape != depth.shape:
            raise ValueError("mask shape mismatch")
        valid &= m
    v, u = np.indices(depth.shape)
    z = depth[valid] / depth_scale
    x = (u[valid] - cx) * z / fx
    y = (v[valid] - cy) * z / fy
    return np.column_stack((x, y, z)).astype(np.float64, copy=False)

import numpy as np

def fit_plane_svd(points: np.ndarray) -> np.ndarray:
    pts = np.asarray(points, dtype=np.float64)
    if pts.ndim != 2 or pts.shape[1] != 3 or len(pts) < 3 or not np.all(np.isfinite(pts)):
        raise ValueError("need at least 3 finite 3D points")
    centroid = pts.mean(axis=0)
    centered = pts - centroid
    if np.linalg.matrix_rank(centered) < 2:
        raise ValueError("point set does not define a unique plane")
    _, _, vh = np.linalg.svd(centered, full_matrices=False)
    n = vh[-1]
    n = n / np.linalg.norm(n)
    for value in n:
        if abs(value) > 1e-12:
            if value < 0:
                n = -n
            break
    d = -float(np.dot(n, centroid))
    return np.array([n[0], n[1], n[2], d], dtype=np.float64)

import numpy as np

def bbox_from_mask(mask: np.ndarray):
    m = np.asarray(mask)
    if m.ndim != 2:
        raise ValueError("mask must be 2D")
    ys, xs = np.nonzero(m)
    if len(xs) == 0:
        return None
    return (int(xs.min()), int(ys.min()), int(xs.max() + 1), int(ys.max() + 1))

