from torch import nn

class ConvBNReLU(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3):
        super().__init__()
        if kernel_size <= 0 or kernel_size % 2 == 0:
            raise ValueError("kernel_size must be a positive odd integer")
        self.block = nn.Sequential(
            nn.Conv2d(
                in_channels, out_channels,
                kernel_size=kernel_size,
                stride=1,
                padding=kernel_size // 2,
                bias=False
            ),
            nn.BatchNorm2d(out_channels),
            nn.ReLU(inplace=True),
        )

    def forward(self, x):
        return self.block(x)

import torch
import torch.nn.functional as F

def binary_focal_loss_with_logits(
    logits, targets, alpha=0.25, gamma=2.0, reduction="mean"
):
    if logits.shape != targets.shape:
        raise ValueError("shape mismatch")
    if reduction not in ("none", "mean", "sum"):
        raise ValueError("invalid reduction")
    targets = targets.to(dtype=logits.dtype)
    bce = F.binary_cross_entropy_with_logits(logits, targets, reduction="none")
    p = torch.sigmoid(logits)
    pt = torch.where(targets == 1, p, 1 - p)
    alpha_t = torch.where(
        targets == 1,
        torch.as_tensor(alpha, dtype=logits.dtype, device=logits.device),
        torch.as_tensor(1 - alpha, dtype=logits.dtype, device=logits.device),
    )
    loss = alpha_t * (1 - pt).pow(gamma) * bce
    if reduction == "mean":
        return loss.mean()
    if reduction == "sum":
        return loss.sum()
    return loss

import numpy as np

def confusion_matrix(y_true, y_pred, num_classes: int, ignore_index=None) -> np.ndarray:
    yt = np.asarray(y_true).reshape(-1)
    yp = np.asarray(y_pred).reshape(-1)
    if yt.shape != yp.shape or num_classes <= 0:
        raise ValueError("invalid inputs")
    if ignore_index is not None:
        keep = yt != ignore_index
        yt, yp = yt[keep], yp[keep]
    if np.any((yt < 0) | (yt >= num_classes) | (yp < 0) | (yp >= num_classes)):
        raise ValueError("class id out of range")
    encoded = yt.astype(np.int64) * num_classes + yp.astype(np.int64)
    counts = np.bincount(encoded, minlength=num_classes * num_classes)
    return counts.reshape(num_classes, num_classes).astype(np.int64, copy=False)

import torch

@torch.no_grad()
def update_ema(ema_model, model, decay: float) -> None:
    if not (0.0 <= decay <= 1.0):
        raise ValueError("decay must be in [0,1]")
    src_params = dict(model.named_parameters())
    ema_params = dict(ema_model.named_parameters())
    if src_params.keys() != ema_params.keys():
        raise ValueError("parameter names do not match")
    for name, ema_p in ema_params.items():
        ema_p.mul_(decay).add_(src_params[name].detach(), alpha=1.0 - decay)

    src_buffers = dict(model.named_buffers())
    ema_buffers = dict(ema_model.named_buffers())
    if src_buffers.keys() != ema_buffers.keys():
        raise ValueError("buffer names do not match")
    for name, ema_b in ema_buffers.items():
        ema_b.copy_(src_buffers[name].detach())

def freeze_for_finetuning(model, trainable_prefixes) -> int:
    prefixes = tuple(trainable_prefixes)
    trainable = 0
    for name, param in model.named_parameters():
        flag = any(name.startswith(prefix) for prefix in prefixes)
        param.requires_grad_(flag)
        if flag:
            trainable += param.numel()
    return int(trainable)

import numpy as np

def _single_iou(a, b):
    lt = np.maximum(a[:2], b[:2])
    rb = np.minimum(a[2:], b[2:])
    wh = np.clip(rb - lt, 0.0, None)
    inter = wh[0] * wh[1]
    aa = max(0.0, a[2]-a[0]) * max(0.0, a[3]-a[1])
    ab = max(0.0, b[2]-b[0]) * max(0.0, b[3]-b[1])
    union = aa + ab - inter
    return 0.0 if union <= 0 else float(inter / union)

def weighted_box_fusion(boxes, scores, iou_threshold=0.55):
    boxes = np.asarray(boxes, dtype=np.float64)
    scores = np.asarray(scores, dtype=np.float64)
    if boxes.ndim != 2 or boxes.shape[1] != 4 or scores.shape != (len(boxes),):
        raise ValueError("invalid shapes")
    if np.any(scores < 0):
        raise ValueError("scores must be non-negative")
    order = np.lexsort((np.arange(len(scores)), -scores))
    clusters = []

    def fused(cluster):
        idx = np.asarray(cluster, dtype=int)
        w = scores[idx]
        if w.sum() == 0:
            box = boxes[idx].mean(axis=0)
        else:
            box = np.average(boxes[idx], axis=0, weights=w)
        score = float(scores[idx].mean())
        return box, score

    for idx in order:
        placed = False
        for cluster in clusters:
            fbox, _ = fused(cluster)
            if _single_iou(boxes[idx], fbox) >= iou_threshold:
                cluster.append(int(idx))
                placed = True
                break
        if not placed:
            clusters.append([int(idx)])

    if not clusters:
        return np.empty((0,4), dtype=np.float64), np.empty((0,), dtype=np.float64)
    fboxes, fscores = zip(*(fused(c) for c in clusters))
    return np.stack(fboxes), np.asarray(fscores, dtype=np.float64)

import numpy as np

def update_centroid_tracks(prev_tracks, detections, max_distance: float) -> dict:
    if max_distance < 0:
        raise ValueError("max_distance must be non-negative")
    det = np.asarray(detections, dtype=np.float64)
    if det.ndim != 2 or det.shape[1] != 2:
        raise ValueError("detections must have shape (N,2)")
    tracks = {int(k): np.asarray(v, dtype=np.float64) for k, v in prev_tracks.items()}
    if any(v.shape != (2,) for v in tracks.values()):
        raise ValueError("invalid previous centroid")

    candidates = []
    for tid, center in tracks.items():
        for j, d in enumerate(det):
            distance = float(np.linalg.norm(center - d))
            if distance <= max_distance:
                candidates.append((distance, tid, j))
    candidates.sort(key=lambda x: (x[0], x[1], x[2]))

    used_tracks = set()
    used_det = set()
    out = {}
    for _, tid, j in candidates:
        if tid not in used_tracks and j not in used_det:
            out[tid] = det[j].copy()
            used_tracks.add(tid)
            used_det.add(j)

    next_id = (max(tracks) + 1) if tracks else 0
    for j, d in enumerate(det):
        if j not in used_det:
            out[next_id] = d.copy()
            next_id += 1
    return out
